type Uploader struct {
	client *s3.Client
	bucket string
}

func (u *Uploader) Upload(ctx context.Context, key string, body io.Reader) error {
	_, err := u.client.PutObject(ctx, &s3.PutObjectInput{Bucket: &u.bucket, Key: &key, Body: body})
	return err
}

func (u *Uploader) Exists(ctx context.Context, key string) (bool, error) {
	_, err := u.client.HeadObject(ctx, &s3.HeadObjectInput{Bucket: &u.bucket, Key: &key})
	var nf *types.NotFound
	if errors.As(err, &nf) { return false, nil }
	return err == nil, err
}

